package org.sleepwell.app;
import org.junit.Test;import java.util.*;import static org.junit.Assert.*;
/** Temporal acceptance only, with unmodified original model gates and default grouping decisions. */
public final class SoundSensitivityTest {
 List<String> run(SoundSensitivity policy,String category,int count){List<String> events=new ArrayList<>();SoundAnalysis.Group group=new SoundAnalysis.Group((at,n,c,s)->events.add(at+":"+n+":"+c+":"+s),policy);for(int n=0;n<count;n++)group.add(1000+n*975,new SoundAnalysis.Result(category,.8));group.flush();return events;}
 @Test public void absentPolicyDefaultsMatchTheOriginalTwoWindowContractForAllClasses(){for(String key:SoundSensitivity.CATEGORIES){assertEquals(2,SoundSensitivity.DEFAULT.windows(key));assertTrue(run(SoundSensitivity.DEFAULT,key,1).isEmpty());assertEquals(List.of("1000:2:"+key+":0.8"),run(SoundSensitivity.DEFAULT,key,2));}assertEquals(2,SoundSensitivity.DEFAULT.windows("noise"));}
 @Test public void minimumOneTwoThreeWindowsChangesOnlyTemporalAcceptance(){for(String key:SoundSensitivity.CATEGORIES)for(int minimum=1;minimum<=3;minimum++){SoundSensitivity selected=SoundSensitivity.DEFAULT.with(key,minimum);for(int n=1;n<minimum;n++)assertTrue(run(selected,key,n).isEmpty());assertEquals(1,run(selected,key,minimum).size());}}
 @Test public void editingOneClassLeavesEveryOtherClassAndOtherSoundsUnchanged(){SoundSensitivity selected=SoundSensitivity.DEFAULT.with("snoring",1).with("cough",3);for(String key:SoundSensitivity.CATEGORIES)assertEquals(key.equals("snoring")?1:key.equals("cough")?3:2,selected.windows(key));assertTrue(run(selected,"noise",1).isEmpty());assertEquals(1,run(selected,"noise",2).size());assertEquals(2,SoundSensitivity.DEFAULT.windows("snoring"));}
 @Test public void snapshotCopiesItsInputAndClipBudgetRetainsThatExactRunPolicy(){Map<String,Integer> values=new HashMap<>();for(String key:SoundSensitivity.CATEGORIES)values.put(key,2);SoundSensitivity snapshot=new SoundSensitivity(values);ClipBudget budget=new ClipBudget(snapshot);values.put("snoring",1);SoundSensitivity next=snapshot.with("snoring",3);assertEquals(2,budget.sensitivity.windows("snoring"));assertEquals(3,next.windows("snoring"));assertSame(snapshot,budget.sensitivity);}
 @Test public void silenceAndChangedCategoryCannotBridgeARequiredThreeWindowEvent(){List<String> out=new ArrayList<>();SoundAnalysis.Group group=new SoundAnalysis.Group((a,n,c,s)->out.add(c),SoundSensitivity.DEFAULT.with("snoring",3));group.add(1,new SoundAnalysis.Result("snoring",.9));group.add(976,new SoundAnalysis.Result("snoring",.9));group.add(1951,null);group.add(2926,new SoundAnalysis.Result("snoring",.9));group.add(3901,new SoundAnalysis.Result("speech",.9));group.flush();assertTrue(out.isEmpty());}
 @Test public void tenWindowBoundAndIdempotentFlushRemainExact(){SoundSensitivity selected=SoundSensitivity.DEFAULT.with("snoring",3);List<Integer> windows=new ArrayList<>();List<Long> starts=new ArrayList<>();SoundAnalysis.Group bounded=new SoundAnalysis.Group((at,n,c,score)->{windows.add(n);starts.add(at);assertEquals(.8,score,1e-12);},selected);for(int n=0;n<13;n++)bounded.add(1000+n*975,new SoundAnalysis.Result("snoring",.8));bounded.flush();assertEquals(List.of(10,3),windows);assertEquals(List.of(1000L,10750L),starts);List<Integer> out=new ArrayList<>();SoundAnalysis.Group group=new SoundAnalysis.Group((a,n,c,s)->out.add(n),selected);group.add(1,new SoundAnalysis.Result("snoring",.9));group.flush();group.flush();assertTrue(out.isEmpty());}
 @Test public void shortEventsKeepActualStartWindowsAndOriginalMeanScore(){List<String> out=new ArrayList<>();SoundAnalysis.Group group=new SoundAnalysis.Group((at,n,c,s)->out.add(at+":"+n+":"+s),SoundSensitivity.DEFAULT.with("cough",1));group.add(5000,new SoundAnalysis.Result("cough",.73));group.flush();assertEquals(List.of("5000:1:0.73"),out);}
 @Test public void sensitivityNeverChangesClassifierScoreOrMarginDecisions(){float[] rejected=new float[521];rejected[38]=.59f;SoundAnalysis.Result result=SoundAnalysis.classify(rejected);assertEquals("noise",result.category);for(int minimum=1;minimum<=3;minimum++){List<String> out=new ArrayList<>();SoundAnalysis.Group group=new SoundAnalysis.Group((a,n,c,s)->out.add(c),SoundSensitivity.DEFAULT.with("snoring",minimum));group.add(1,result);group.add(976,result);group.flush();assertEquals(List.of("noise"),out);assertEquals(.59f,rejected[38],0);}}
 @Test public void invalidPolicyKeysValuesAndMissingClassesReject(){Map<String,Integer> all=new HashMap<>();for(String key:SoundSensitivity.CATEGORIES)all.put(key,2);for(int n:new int[]{0,4,-1}){Map<String,Integer> invalid=new HashMap<>(all);invalid.put("snoring",n);assertThrows(IllegalArgumentException.class,()->new SoundSensitivity(invalid));}all.remove("speech");assertThrows(IllegalArgumentException.class,()->new SoundSensitivity(all));assertThrows(IllegalArgumentException.class,()->SoundSensitivity.DEFAULT.with("noise",1));}
 @Test public void oneWindowStillNeedsAFullUnpaddedClassifierFrame(){List<Integer> counts=new ArrayList<>();SoundAnalysisStream.Model model=new SoundAnalysisStream.Model(){public float[] infer(float[] pcm){float[] scores=new float[521];scores[42]=.9f;return scores;}public void close(){}};try(SoundAnalysisStream stream=new SoundAnalysisStream(()->model,(at,n,c,s)->{assertEquals("cough",c);counts.add(n);},()->fail(),SoundSensitivity.DEFAULT.with("cough",1))){stream.accept(new short[15599],15599,2000);assertTrue(counts.isEmpty());stream.accept(new short[1],1,2001);}assertEquals(List.of(1),counts);}
 @Test public void newStreamUsesItsImmutableSnapshotAcrossLaterSettingsCopies(){List<Integer> counts=new ArrayList<>();SoundSensitivity original=SoundSensitivity.DEFAULT.with("snoring",3);SoundAnalysisStream.Model model=new SoundAnalysisStream.Model(){public float[] infer(float[] pcm){float[] scores=new float[521];scores[38]=.9f;return scores;}public void close(){}};try(SoundAnalysisStream stream=new SoundAnalysisStream(()->model,(at,n,c,s)->counts.add(n),()->fail(),original)){SoundSensitivity next=original.with("snoring",1);assertEquals(1,next.windows("snoring"));stream.accept(new short[31200],31200,4000);}assertTrue(counts.isEmpty());}
 @Test public void sharedSonarDownsamplingHonorsPolicyWithoutJoiningRealGaps(){SonarSoundPipelineTest.Fake fake=new SonarSoundPipelineTest.Fake();fake.speech=true;List<Integer> counts=new ArrayList<>();try(SonarSoundPipeline pipeline=new SonarSoundPipeline(fake,(a,n,c,s)->counts.add(n),SonarSoundPipelineTest.WALL,SonarSoundPipelineTest.ORIGIN,SoundSensitivity.DEFAULT.with("speech",1))){SonarSoundPipelineTest helper=new SonarSoundPipelineTest();helper.blocks(pipeline,0,25);pipeline.gap();helper.blocks(pipeline,26,25);}assertEquals(List.of(1,1),counts);assertEquals(2,fake.calls);assertEquals(1,fake.closed);}
}
